"""Create an offline interactive visual review from actual iteration evidence."""
from pathlib import Path
import json,base64,html
ROOT=Path(__file__).resolve().parents[1]
rounds=[]
for folder in sorted((ROOT/'iterations').iterdir()):
    if not (folder/'capture.json').exists():continue
    record=json.loads((folder/'capture.json').read_text())
    review=(folder/'REVIEW.md').read_text() if (folder/'REVIEW.md').exists() else 'בדיקת ההרצה הממושכת עדיין מתבצעת.'
    rounds.append({'number':folder.name,'image':'data:image/jpeg;base64,'+base64.b64encode((folder/'contact-sheet.jpg').read_bytes()).decode(),
        'review':review,'time':record['completedAt'],'sha':record['sourceSha256'],'shots':len(record['screens']),
        'cases':[{'file':s['file'],'triangles':s['metrics']['triangles'],'calls':s['metrics']['drawCalls']} for s in record['screens'][:4]]})
template='''<!doctype html><html lang="he" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; img-src data:; style-src 'unsafe-inline'; script-src 'unsafe-inline'; base-uri 'none'"><title>מצר הדמדומים · שמונה סבבי ביקורת</title><style>
*{box-sizing:border-box}body{margin:0;background:#0e202c;color:#e6dfcb;font:14px/1.6 Arial,sans-serif}main{max-width:1280px;margin:auto;padding:24px}header{display:flex;justify-content:space-between;align-items:center;gap:20px;border-bottom:1px solid #d2b38e33;padding-bottom:20px;margin-bottom:25px}h1{font-size:clamp(25px,4vw,40px);font-weight:400;margin:0}h2{font-weight:400;font-size:20px}p{color:#b6c6bd;margin:8px 0}a{color:#dfb487;text-decoration:none}a:hover{text-decoration:underline}.links{display:flex;gap:8px;flex-wrap:wrap}.links a,select{display:inline-flex;align-items:center;min-height:44px;border:1px solid #a9bdad44;background:#18333e;color:#e6ddc3;border-radius:4px;padding:8px 14px;font:inherit}label{display:flex;align-items:center;gap:10px}.toolbar{display:flex;gap:20px;align-items:center;flex-wrap:wrap;margin-bottom:14px}.stage{position:relative;aspect-ratio:1280/700;overflow:hidden;background:#10232f;border:1px solid #9cafab33;direction:ltr}.stage img{width:100%;display:block;position:absolute;left:0;top:0}.top{position:absolute;inset:0;overflow:hidden;clip-path:inset(0 50% 0 0)}.seam{position:absolute;left:50%;top:0;bottom:0;border-left:2px solid #eed1a7;pointer-events:none}.pill{position:absolute;bottom:12px;background:#10232fe8;color:#e1c29a;padding:6px 12px;border-radius:3px;font:12px monospace}.pill.a{right:12px;left:auto}.pill.b{left:12px;right:auto}.range{width:100%;min-height:44px;accent-color:#d3a16c;margin:5px 0}.legend{font-size:12px;color:#a9c0b6}.grid{display:grid;grid-template-columns:1fr 1fr;gap:22px}article{background:#132d39;border:1px solid #a6b6a322;border-radius:5px;padding:17px;min-width:0}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.9 Arial,sans-serif;color:#bdcfc2;margin:0}table{width:100%;border-collapse:collapse;font-size:12px}td,th{text-align:right;padding:9px;border-bottom:1px solid #b7c3ad22}th{color:#d5b389;font-weight:400}code{font:10px monospace;overflow-wrap:anywhere;color:#9ab9b6}footer{margin:24px 0 12px;border-top:1px solid #b8c5b022;padding-top:12px;font-size:12px;color:#99afa6}:focus-visible{outline:2px solid #e8bd84;outline-offset:4px}@media(max-width:650px){main{padding:16px}header{display:block}.links{margin-top:15px}.grid{grid-template-columns:1fr}.toolbar{gap:8px;justify-content:space-between}select{padding:6px 10px}.stage{aspect-ratio:1280/760}.pill{font-size:9px;bottom:5px;padding:3px 7px}th,td{padding:6px}label{font-size:12px}}
</style></head><body><main><header><div><p>מצר הדמדומים / NAVAL V7</p><h1>שמונה סבבים. ים אחד.</h1><p>צילומים אמיתיים, ביקורת ותיקון בכל סבב.</p></div><nav class="links"><a href="index.html">לסצנה האינטראקטיבית ↗</a><a href="REPORT.md">הדוח המלא</a><a href="ASSET-WEIGHTS.md">משקלי הנכסים</a></nav></header><div class="toolbar"><label>סבב מוקדם <select id="left" aria-label="בחירת סבב מוקדם"></select></label><label>סבב להשוואה <select id="right" aria-label="בחירת סבב להשוואה"></select></label><span class="legend" id="counts"></span></div><div class="stage"><img id="image-a" alt="ארבעת צילומי החובה בסבב המוקדם"><div class="top" id="top"><img id="image-b" alt="ארבעת צילומי החובה בסבב ההשוואה"></div><div class="seam" id="seam"></div><span class="pill a" id="pill-a"></span><span class="pill b" id="pill-b"></span></div><label for="wipe" class="legend">גררו להשוואה בין הסבבים</label><input class="range" id="wipe" type="range" min="0" max="100" value="50" dir="ltr" aria-label="אחוז החשיפה של סבב ההשוואה"><div class="grid"><article><h2 id="title-a"></h2><div id="data-a"></div><p><a id="review-a">פתיחת ביקורת הסבב</a></p><pre id="text-a"></pre></article><article><h2 id="title-b"></h2><div id="data-b"></div><p><a id="review-b">פתיחת ביקורת הסבב</a></p><pre id="text-b"></pre></article></div><footer>390×844 ו־844×390, קרוב ורחוק. צילומי המקור המלאים ונתוני המצלמה שמורים בכל תיקיית סבב. אין בקשת רשת בדף הזה. מדידות FPS בדוח הן של SwiftShader בתוכנה; אין כאן אישור 30fps בטלפון פיזי.</footer></main><script id="round-data" type="application/json">__DATA__</script><script>
const rounds=JSON.parse(document.getElementById('round-data').textContent),get=id=>document.getElementById(id);let a=0,b=rounds.length-1;
for(const id of ['left','right'])for(let i=0;i<rounds.length;i++){const o=document.createElement('option');o.value=i;o.textContent='סבב '+rounds[i].number;get(id).append(o);}get('right').value=b;
function table(record){const t=document.createElement('table'),head=document.createElement('tr');for(const text of ['צילום','משולשים','קריאות ציור']){const th=document.createElement('th');th.textContent=text;head.append(th);}t.append(head);for(const row of record.cases){const tr=document.createElement('tr');for(const text of [row.file,row.triangles.toLocaleString('en-US'),row.calls]){const td=document.createElement('td');td.textContent=text;tr.append(td);}t.append(tr);}return t;}
function draw(){for(const [s,r]of [['a',rounds[a]],['b',rounds[b]]]){get('image-'+s).src=r.image;get('pill-'+s).textContent='ITERATION / '+r.number;get('title-'+s).textContent='סבב '+r.number;get('text-'+s).textContent=r.review;get('data-'+s).replaceChildren(table(r));get('review-'+s).href='iterations/'+r.number+'/REVIEW.md';}get('counts').textContent=rounds[a].shots+' מול '+rounds[b].shots+' צילומים';}
get('left').onchange=e=>{a=Number(e.target.value);draw();};get('right').onchange=e=>{b=Number(e.target.value);draw();};get('wipe').oninput=e=>{const x=e.target.value;get('top').style.clipPath='inset(0 '+(100-Number(x))+'% 0 0)';get('seam').style.left=x+'%';e.target.setAttribute('aria-valuetext',x+' אחוז');};draw();
</script></body></html>'''
(ROOT/'review.html').write_text(template.replace('שמונה סבבי ביקורת',str(len(rounds))+' סבבי ביקורת').replace('שמונה סבבים. ים אחד.',str(len(rounds))+' סבבים. ים אחד.').replace('__DATA__',json.dumps(rounds,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')))
print('Built offline review:',len(rounds),'rounds,',(ROOT/'review.html').stat().st_size,'bytes')
